export default async function (e) {
    // 1. Only intercept requests targeting the 'copilot' action
    if (e.data.slug !== 'copilot') {
        return e.data; // Let other actions pass through untouched
    }

    const userPrompt = e?.data?.vars?.prompt;
    if (!userPrompt) {
        return e.data;
    }

    console.log("Intercepted Copilot request. Running vector search for: " + userPrompt);

    try {
        // 2. Perform a semantic vector search on the 'articles' collection
        // $db.records.searchVector returns an array of tuples: [[record, score], [record, score], ...]
        const limit = 3;
        const vec = await $ai.embed(userPrompt);
        const searchResults = await $db.records.searchVector("articles", "content", vec, limit);

        let contextString = '';

        if (searchResults && searchResults.length > 0) {
            console.log(`Found ${searchResults.length} context documents. Injecting...`);

            // 3. Extract the record object from item[0] of each returned [record, distance] pair
            contextString = searchResults.map(item => {
                const record = item[0];
                const data = record?.data || record || {};
                return `Title: ${data.title || 'Untitled'}\nContent: ${data.content || ''}`;
            }).join('\n\n---\n\n');
        } else {
            console.log("No context documents found in vector space.");
            contextString = "No relevant official documentation found in the database.";
        }

        // 4. Inject the formatted context into the payload bound for Gemini/Groq
        e.data.vars.context = contextString;

    } catch (err) {
        console.log("Vector search failed: " + err);
        e.data.vars.context = "Error retrieving context from database.";
    }

    // 5. Return the modified payload back to the ApexKit inference engine
    return e.data;
}

export default async function (e) {
    const data = e.record?.data || e.data;
    if (data && data.title && (!data.slug || data.slug.trim() === '')) {
        data.slug = $util.slugify(data.title);
    }
    return data;
}
